import{execFileSync}from'node:child_process';import{readFile,writeFile,stat}from'node:fs/promises';const files=[...new Set(execFileSync('git',['ls-files','--modified','--others','--exclude-standard','-z']).toString().split('\0').filter(Boolean))];const findings=[];let scanned=0;const pattern=/(?:sk-(?:proj-|or-v1-)?[A-Za-z0-9_-]{24,}|gh[pousr]_[A-Za-z0-9]{30,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|Bearer\s+[A-Za-z0-9_.-]{24,})/g;for(const path of files){if(!(await stat(path)).isFile())continue;const b=await readFile(path);if(b.includes(0))continue;scanned++;if(pattern.test(b.toString()))findings.push(path);pattern.lastIndex=0;}await writeFile('.local/unified-angles-auto-sync-2026-10-20/credential-scan.json',JSON.stringify({scanned,findings},null,2));console.log({scanned,findings});if(findings.length)process.exitCode=1;
